import React, { useEffect, useState } from 'react';
import {
  View,
  Text,
  FlatList,
  TouchableOpacity,
  StyleSheet,
  ActivityIndicator,
  Alert,
} from 'react-native';
import { useNavigation } from '@react-navigation/native';
import {
  collection,
  onSnapshot,
  query,
  orderBy,
  deleteDoc,
  doc,
} from 'firebase/firestore';
import { firestore, auth } from '../services/firebaseConfig';
import { NativeStackNavigationProp } from '@react-navigation/native-stack';
import type { ListaRotasPrincipais } from '../types';
import { LinearGradient } from 'expo-linear-gradient';

type NavigationProp = NativeStackNavigationProp<ListaRotasPrincipais, 'Escalas'>;

interface Escala {
  id: string;
  data: string;
  [key: string]: any;
}

// Neumorphic container for alto relevo effect
const NeumorphicContainer = ({ children, style }: any) => (
  <View style={[styles.neumorphicOuter, style]}>
    <View style={styles.neumorphicInner}>{children}</View>
  </View>
);

const UIDS_PERMITIDOS = [
  'qAvyxYtraUPmd06d3jufwqPi7vo2',
  'g8KmZsmMqfPEqAM3NWF7qs33Gid2',
  'bVpx7GAuLuTbRVWfPOT57vgO9cL2',
  // Adicione outros UIDs aqui
];

export default function TelaListaEscalas(): JSX.Element {
  const navigation = useNavigation<NavigationProp>();
  const [escalas, setEscalas] = useState<Escala[]>([]);
  const [uidAtual, setUidAtual] = useState<string | null>(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    const uid = auth.currentUser?.uid ?? null;
    setUidAtual(uid);

    const escalasQuery = query(
      collection(firestore, 'escalas'),
      orderBy('criadoEm', 'desc')
    );

    const unsubscribe = onSnapshot(escalasQuery, (querySnapshot) => {
      const data = querySnapshot.docs.map(doc => {
        const docData = doc.data();
        let dataFormatada = '';
        if (docData.data) {
          dataFormatada = docData.data;
        } else if (docData.criadoEm?.toDate) {
          dataFormatada = docData.criadoEm.toDate().toLocaleDateString();
        }
        return {
          id: doc.id,
          data: dataFormatada,
          ...docData,
        } as Escala;
      });
      setEscalas(data);
      setLoading(false);
    }, (error) => {
      console.log('Erro ao buscar dados:', error);
      setLoading(false);
    });

    return () => unsubscribe();
  }, []);

  const excluirEscala = async (id: string) => {
    if (!uidAtual || !UIDS_PERMITIDOS.includes(uidAtual)) return;
    try {
      await auth.currentUser?.getIdToken(true);
      await deleteDoc(doc(firestore, 'escalas', id));
      setEscalas(prev => prev.filter(escala => escala.id !== id));
    } catch (error: any) {
      console.log('Erro ao excluir escala:', error);
    }
  };

  const permitido = !!uidAtual && UIDS_PERMITIDOS.includes(uidAtual);

  const renderItem = ({ item }: { item: Escala }) => (
    <NeumorphicContainer style={styles.escalaItem}>
      <View style={styles.escalaContent}>
        <TouchableOpacity
          style={{ flex: 1 }}
          onPress={() => navigation.navigate('DetalhesEscala', { id: item.id })}
        >
          <Text style={styles.escalaTexto}>
            {item.data ? `Data: ${item.data}` : `ID: ${item.id}`}
          </Text>
        </TouchableOpacity>
        {permitido && (
          <TouchableOpacity
            style={styles.botaoExcluir}
            onPress={() => excluirEscala(item.id)}
          >
            <Text style={styles.textoBotao}>🗑️</Text>
          </TouchableOpacity>
        )}
      </View>
    </NeumorphicContainer>
  );

  return (
    <LinearGradient
      colors={['#18152a', '#181a2a']}
      style={styles.bg}
      start={{ x: 0, y: 0 }}
      end={{ x: 0, y: 1 }}
    >
      <View style={styles.container}>
        <View style={styles.headerBar}>
          <TouchableOpacity style={styles.headerButton} onPress={() => navigation.navigate('Inicio')}>
            <Text style={styles.headerButtonText}>🏠</Text>
          </TouchableOpacity>
          <Text style={styles.headerTitle}>Lista de Escalas</Text>
          <TouchableOpacity style={styles.headerButton} onPress={() => navigation.goBack()}>
            <Text style={styles.headerButtonText}>🔙</Text>
          </TouchableOpacity>
        </View>
        {loading ? (
          <ActivityIndicator size="large" color="#ff9800" style={{ marginTop: 40 }} />
        ) : (
          <FlatList
            data={escalas}
            keyExtractor={(item) => item.id}
            ListEmptyComponent={
              <Text style={styles.emptyText}>
                Nenhuma escala encontrada.
              </Text>
            }
            renderItem={renderItem}
            contentContainerStyle={styles.list}
          />
        )}

        {permitido && (
          <NeumorphicContainer style={styles.fab}>
            <TouchableOpacity
              style={{ flex: 1, justifyContent: 'center', alignItems: 'center' }}
              onPress={() => navigation.navigate('CriarEscala')}
            >
              <Text style={styles.fabTexto}>+</Text>
            </TouchableOpacity>
          </NeumorphicContainer>
        )}
      </View>
    </LinearGradient>
  );
}

