import React, { useEffect, useState } from 'react';
import { View, ActivityIndicator, StyleSheet, Platform } from 'react-native';
import { NavigationContainer } from '@react-navigation/native';
import { onAuthStateChanged, User } from 'firebase/auth';

import AuthNavigator from './src/navigation/AuthNavigator';
import AppNavigator from './src/navigation/AppNavigator';
import { auth, firestore } from './src/services/firebaseConfig';
import Toast from 'react-native-toast-message';

// --- Notificações Expo ---
import * as Notifications from 'expo-notifications';
import Constants from 'expo-constants';
import { setDoc, doc } from 'firebase/firestore';

function useRegisterForPushNotifications(usuario: User | null) {
  useEffect(() => {
    async function register() {
      if (Platform.OS === 'web') return; // Notificações push nativas não funcionam no web
      if (Constants.isDevice && usuario) {
        const { status: existingStatus } = await Notifications.getPermissionsAsync();
        let finalStatus = existingStatus;
        if (existingStatus !== 'granted') {
          const { status } = await Notifications.requestPermissionsAsync();
          finalStatus = status;
        }
        if (finalStatus !== 'granted') {
          alert('Permissão para notificações negada!');
          return;
        }
        const token = (await Notifications.getExpoPushTokenAsync()).data;
        // Salva o token no Firestore, vinculado ao usuário logado
        await setDoc(
          doc(firestore, 'usuarios', usuario.uid),
          { expoPushToken: token },
          { merge: true }
        );
        console.log('Expo Push Token salvo:', token);
      } else if (!Constants.isDevice) {
        alert('Precisa de um dispositivo físico para notificações push');
      }
    }
    register();
  }, [usuario]);
}
// --- Fim Notificações Expo ---

// --- Função InstallPWAButton ---
function InstallPWAButton() {
  const [deferredPrompt, setDeferredPrompt] = useState(null);
  const [showButton, setShowButton] = useState(false);

  useEffect(() => {
    const handler = (e) => {
      e.preventDefault();
      setDeferredPrompt(e);
      setShowButton(true);
    };
    window.addEventListener('beforeinstallprompt', handler);

    return () => window.removeEventListener('beforeinstallprompt', handler);
  }, []);

  const handleInstallClick = async () => {
    if (deferredPrompt) {
      deferredPrompt.prompt();
      await deferredPrompt.userChoice;
      setDeferredPrompt(null);
      setShowButton(false);
    }
  };

  if (!showButton) return null;

  return (
    <button onClick={handleInstallClick} style={{ padding: 12, fontSize: 16 }}>
      Instalar App
    </button>
  );
}
// --- Fim InstallPWAButton ---

// --- Configuração de linking para web/PWA ---
const linking = {
  prefixes: [window.location.origin + '/'],
  config: {
    screens: {
      Inicio: '',
      CriarEscala: 'criar-escala',
      Escalas: 'escalas',
      DetalhesEscala: 'detalhes-escala',
      Repertorios: 'repertorios',
      AdicionarRepertorio: 'adicionar-repertorio',
      DetalheRepertorio: 'detalhe-repertorio',
      VisualizarArquivo: 'visualizar-arquivo',
      Presenca: 'presenca',
      Avisos: 'avisos',
      Ensaios: 'ensaios',
      Aniversariantes: 'aniversariantes',
      Agenda: 'agenda',
    },
  },
};
// --- Fim linking ---

export default function App(): JSX.Element {
  const [usuario, setUsuario] = useState<User | null>(null);
  const [carregando, setCarregando] = useState(true);

  // Observa mudanças no estado de autenticação
  useEffect(() => {
    const unsubscribe = onAuthStateChanged(auth, async (usuarioAtual: User | null) => {
      // Só considera logado se o email estiver verificado
      if (usuarioAtual && usuarioAtual.emailVerified) {
        setUsuario(usuarioAtual);
      } else {
        setUsuario(null);
      }
      setCarregando(false);
    });

    return unsubscribe; // limpa o observer ao desmontar
  }, []);

  useRegisterForPushNotifications(usuario);

  // Mostra indicador de carregamento enquanto verifica login
  if (carregando) {
    return (
      <View style={styles.loadingContainer}>
        <ActivityIndicator size="large" color="#007AFF" />
      </View>
    );
  }

  return (
    <NavigationContainer linking={linking}>
      {/* Alterna entre as rotas com base no login */}
      {usuario ? <AppNavigator /> : <AuthNavigator />}
      <InstallPWAButton />
      <Toast />
    </NavigationContainer>
  );
}

const styles = StyleSheet.create({
  loadingContainer: {
    flex: 1,
    justifyContent: 'center',
    alignItems: 'center',
    backgroundColor: '#fff',
  },
});